                foreach(string key in QuickWidgetLayout.Keys)for(int c=1;c<=4;c++)for(int r=1;r<=5;r++){
                    model.Restore(baseline);model.Resize(key,c,r,false);Require(model.Fits(),"horizontal/regular layout bounds "+key);var item=model.Find(key);Require(item.Columns==(key=="media"?Math.Max(2,c):c)&&item.Rows==(QuickWidgetLayout.Slider(key)?1:key=="media"?Math.Max(2,r):r),"size contract, including media minimum 2 x 2");
                    if(QuickWidgetLayout.Slider(key)){model.Resize(key,c,r,true);Require(model.Find(key).Columns==1&&model.Find(key).Rows==r&&model.Fits(),"vertical slider contract");}
                }
                model.Restore(baseline);model.Move("manager",0,0);Require(model.Find("manager").X==0&&model.Find("manager").Y==0&&model.Fits()&&model.Find("wifi").Y>0,"drag priority displaces overlapping widgets");
                var random=new Random(900);for(int n=0;n<300;n++){string key=QuickWidgetLayout.Keys[random.Next(12)];model.Move(key,random.Next(-2,7),random.Next(0,14));model.Resize(key,random.Next(0,7),random.Next(0,8),random.Next(2)==0);Require(model.Fits(),"repeated moves/resizes must never overlap");}
                model.SetHidden("wifi",true);model.SetHidden("wifi",false);model.Resize("volume",1,5,true);Require(model.Fits()&&model.Save(),"hide/add and persist");var restored=new QuickWidgetLayout(file);Require(State(restored)==State(model),"all positions, sizes and hidden states survive reopening; before="+State(model)+"; after="+State(restored));
                model.Restore(new[]{new QuickWidgetSlot {Key="volume",X=99,Y=-9,Columns=4,Rows=5},new QuickWidgetSlot {Key="volume",Columns=2,Rows=3},new QuickWidgetSlot {Key="foreign",Columns=99,Rows=99}});Require(model.Fits()&&model.Items.Count==12&&model.Find("volume").Rows==1,"invalid/duplicate/unknown settings sanitize without dropping known items");
                model.Restore(new[]{new QuickWidgetSlot {Key="media",Columns=1,Rows=1}});Require(model.Find("media").Columns==2&&model.Find("media").Rows==2&&model.Fits(),"stored media sizes smaller than 2 x 2 migrate safely");var presentation=new QuickWidgetLayout(null,true);presentation.Resize("media",4,1,false);Require(presentation.Find("media").Rows==1&&presentation.Fits()&&!presentation.Save(),"temporary idle media row cannot be persisted as a user layout");
                string orderFile=Path.Combine(folder,"quick-toggle-order-9.json");var order=new QuickToggleOrder(orderFile);Require(order.Keys.SequenceEqual(QuickToggleOrder.Defaults)&&order.Move("wifi","mute",false),"internal toggle order starts with the actual first row and accepts a move");Require(new QuickToggleOrder(orderFile).Keys.SequenceEqual(order.Keys)&&order.Keys[0]=="wifi","internal toggle order persists independently");File.WriteAllText(orderFile,"[\"bluetooth\",\"foreign\",\"bluetooth\"]");order=new QuickToggleOrder(orderFile);Require(order.Keys.Length==10&&order.Keys.Distinct().Count()==10&&order.Keys[0]=="bluetooth"&&!order.Keys.Contains("foreign"),"invalid toggle orders keep every supported toggle once");
            }finally{foreach(string p in Directory.GetFiles(folder))File.Delete(p);Directory.Delete(folder);}
            checks.Add("UI 9 validates all 20 regular widget sizes, media minimum 2 x 2 and both slider axes, collision-free movement over 300 edits, hidden-item recovery, persistence and invalid layout sanitization without changing UI 8.5 settings");
        }
