                    var defaults=board.Layout.Copy();var activeMedia=shell.Services.Media;shell.Services.Media=new MediaState();quick.Refresh(shell.Power,64,35,false,true,true);await Task.Delay(230);Require(board.DisplayLayout.Find("media").Rows==1&&board.Frames["media"].ActualHeight==64&&State(board.Layout)==folded&&board.DisplayLayout.Find("devices").Y==board.Layout.Find("devices").Y-1,"only the idle default 4 x 2 media contracts to one row and brings lower widgets up without saving");Program.Save(quick.Surface,380,650,Path.Combine(AppLog.Data,"quick9-idle-media.png"));quick.SetExpanded(true);await Task.Delay(220);Require(board.DisplayLayout.Fits()&&board.DisplayLayout.Find("media").Rows==1&&State(board.Layout)==folded,"inline toggles and compact idle media coexist without overlap");quick.SetExpanded(false);await Task.Delay(220);quick.EditLayout(true);Require(board.DisplayLayout.Find("media").Rows==2,"editing restores the saved media size even while idle");quick.EditLayout(false);foreach(var shape in new[]{new[]{2,2},new[]{3,2},new[]{4,3}}){board.Layout.Restore(defaults);board.Layout.Resize("media",shape[0],shape[1],false);board.Reflow(false);Require(board.DisplayLayout.Find("media").Rows==shape[1],"custom media sizes do not automatically compact");}board.Layout.Restore(defaults);board.Reflow(false);shell.Services.Media=activeMedia;quick.Refresh(shell.Power,64,35,false,true,true);await Task.Delay(230);Require(board.DisplayLayout.Find("media").Rows==2&&State(board.Layout)==folded,"active and paused media restore the saved default size");
