                    string initial=State(board.Layout);board.Begin("wifi",true,false);var unchanged=board.Layout.Items;board.PreviewBy(.1,.1);Require(Object.ReferenceEquals(unchanged,board.Layout.Items),"motion inside one grid cell reuses the layout without a reflow");board.PreviewBy(170,340);await Task.Delay(200);Require(board.Layout.Find("wifi").Columns==4&&board.Layout.Find("wifi").Rows==5&&board.Layout.Fits(),"corner drag grows a single tile on both axes");var escapeSource=PresentationSource.FromVisual(board.Frames["wifi"].Resize);board.Frames["wifi"].Resize.RaiseEvent(new KeyEventArgs(Keyboard.PrimaryDevice,escapeSource,Environment.TickCount,Key.Escape){RoutedEvent=Keyboard.PreviewKeyDownEvent});Require(State(board.Layout)==initial&&!board.TimerActive&&quick.IsVisible&&board.Editing,"Escape cancels the whole gesture before the host can hide");
